import{$,$$,status,download,copy,escape}from'./common.js';import{diffLines}from'./vendor.js';
const sample={project:'Something useful',studio:'Tech Buzzs',features:['fast','local','thoughtful'],ready:true,version:1};$('#jsonInput').value=JSON.stringify(sample);$$('[data-tool]').forEach(b=>b.onclick=()=>{$$('.tool').forEach(p=>p.hidden=p.id!==b.dataset.tool);$$('[data-tool]').forEach(t=>t.classList.toggle('active',t===b));status('')});
function parse(minify=false){try{const value=JSON.parse($('#jsonInput').value);$('#jsonInput').value=JSON.stringify(value,null,minify?0:2);$('#jsonStatus').textContent='Valid JSON · '+new TextEncoder().encode($('#jsonInput').value).length+' bytes';$('#jsonStatus').classList.remove('error');return true}catch(e){$('#jsonStatus').textContent=e.message;$('#jsonStatus').classList.add('error');return false}}
$('#format').onclick=()=>parse();$('#minify').onclick=()=>parse(true);$('#sample').onclick=()=>{$('#jsonInput').value=JSON.stringify(sample);parse()};$('#copy').onclick=()=>copy($('#jsonInput').value);$('#download').onclick=()=>{if(parse())download(new Blob([$('#jsonInput').value],{type:'application/json'}),'formatted.json')};$('#compare').onclick=()=>{const before=$('#before').value,after=$('#after').value;if(before.length+after.length>200000){status('Compare text totaling fewer than 200,000 characters.',true);return}const parts=diffLines(before,after);$('#diffResult').innerHTML=parts.map(p=>`<span class="${p.added?'added':p.removed?'removed':''}">${escape((p.added?'+ ':p.removed?'− ':'  ')+p.value)}</span>`).join('')};$('#encode').onclick=()=>{$('#urlOutput').value=encodeURIComponent($('#urlInput').value);status('Encoded as a URL component.')};$('#decode').onclick=()=>{try{$('#urlOutput').value=decodeURIComponent($('#urlInput').value);status('Decoded URL component.')}catch{status('This text contains an invalid percent-encoded sequence.',true)}};$('#copyUrl').onclick=()=>copy($('#urlOutput').value);
function time(){const value=Number($('#timestamp').value);const ms=$('#unit').value==='seconds'?value*1000:value;const date=new Date(ms);if(!$('#timestamp').value.trim()||!Number.isFinite(ms)||isNaN(date.getTime())){status('Enter a valid Unix timestamp.',true);$('#timeResult').textContent='Invalid timestamp';return}$('#timeResult').innerHTML=`<span class="label">UTC</span><p class="code">${date.toISOString()}</p><span class="label">YOUR LOCAL TIME</span><p>${escape(date.toLocaleString())}</p><span class="label">UNIX SECONDS</span><p class="code">${Math.floor(ms/1000)}</p>`;status('Timestamp converted.')};$('#convertTime').onclick=time;$('#now').onclick=()=>{$('#timestamp').value=String($('#unit').value==='seconds'?Math.floor(Date.now()/1000):Date.now());time()};$('#toUnix').onclick=()=>{const s=$('#iso').value;if(!/(Z|[+-]\d\d:\d\d)$/.test(s)){status('Include a timezone, such as Z or +05:30.',true);return}const date=new Date(s);if(isNaN(date.getTime())){status('Enter a valid ISO date.',true);return}$('#unixResult').textContent=Math.floor(date.getTime()/1000)+' seconds · '+date.getTime()+' milliseconds';status('Date converted.')};parse();$('#compare').click();time();
